/* ---- line3d.vert ----
#version 450
layout(location = 0) in vec3 in_pos;
layout(location = 1) in vec3 in_other;   
layout(location = 2) in vec4 in_color;
layout(location = 3) in float in_side;   
layout(location = 4) in float in_width;  

layout(push_constant, row_major) uniform Push {
    mat4 vp;
    vec4 viewport;   // xy = viewport size in pixels
} pc;

layout(location = 0) out vec4 v_color;

void main() {
    vec4 a = pc.vp * vec4(in_pos, 1.0);
    vec4 b = pc.vp * vec4(in_other, 1.0);
    vec2 sa = a.xy / a.w * pc.viewport.xy;
    vec2 sb = b.xy / b.w * pc.viewport.xy;
    vec2 d = sb - sa;
    float len = length(d);
    vec2 dir = len > 1e-6 ? d / len : vec2(1.0, 0.0);
    vec2 nrm = vec2(-dir.y, dir.x);
    vec2 off = (nrm * in_side - dir) * in_width / pc.viewport.xy;   
    gl_Position = a + vec4(off * a.w, 0.0, 0.0);
    gl_Position.z -= 2e-5 * gl_Position.w;                          
    v_color = in_color;
}
*/
