/* ---- quad3d.vert ----
#version 450
layout(location = 0) in vec3 in_pos;
layout(location = 1) in vec4 in_color;
layout(location = 2) in uint in_params;
layout(location = 3) in vec4 in_light;

layout(push_constant, row_major) uniform Push {
    mat4  mvp;
    vec4  model_x;
    vec4  model_y;
    vec4  model_z;
    ivec4 extra;
} pc;

layout(location = 0) out vec3 v_world;
layout(location = 1) out vec3 v_normal;
layout(location = 2) out vec4 v_light;
layout(location = 3) flat out uint v_flags;
layout(location = 4) out vec4 v_color;
layout(location = 5) flat out uvec4 v_params;
layout(location = 6) flat out ivec3 v_origin;
layout(location = 7) out vec3 v_local;
layout(location = 8) out float v_shade;

const vec3 kFaceNormals[7] = vec3[7](vec3(-1.0, 0.0, 0.0), vec3(1.0, 0.0, 0.0), vec3(0.0, -1.0, 0.0),
                                     vec3(0.0, 1.0, 0.0), vec3(0.0, 0.0, -1.0), vec3(0.0, 0.0, 1.0), vec3(0.0));

void main() {
    vec4 p = vec4(in_pos, 1.0);
    gl_Position = pc.mvp * p;
    uvec4 params = uvec4(in_params & 0xFFu, (in_params >> 8) & 0xFFu, (in_params >> 16) & 0xFFu, in_params >> 24);
    vec3 f = kFaceNormals[min(params.y, 6u)];
    v_world  = vec3(dot(pc.model_x, p), dot(pc.model_y, p), dot(pc.model_z, p));
    v_normal = vec3(dot(pc.model_x.xyz, f), dot(pc.model_y.xyz, f), dot(pc.model_z.xyz, f));
    v_light  = in_light;
    v_flags  = uint(pc.extra.w) | ((params.z & 1u) != 0u ? 4u : 0u) | ((params.z & 2u) != 0u ? 8u : 0u) | ((params.z & 4u) != 0u ? 16u : 0u);
    v_color  = in_color;
    v_params = params;
    v_origin = pc.extra.xyz;
    v_local  = in_pos;
    v_shade  = float(params.w);
}
*/
